package com.mavric.healthsqlserver;

import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.ClassPathScanningCandidateComponentProvider;
import org.springframework.mock.web.*;
import org.springframework.web.context.support.AnnotationConfigWebApplicationContext;
import org.springframework.web.context.request.*;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.identity.*;
import com.mavric.health.support.SupportController;
import com.mavric.health.shared.Errors;
import com.mavric.health.tenancy.*;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.audit.TraceContext;
import tools.jackson.databind.ObjectMapper;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class SqlServerIdentityConfigurationTest {
    static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",OTHER="cc000000-0000-4000-8000-000000000001";
    static Object field(Object object,String name)throws Exception{var f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
    static class Harness implements AutoCloseable {
        final MockServletContext servlet=new MockServletContext();final ObjectMapper mapper=new ObjectMapper();final Settings settings=new Settings("health.localhost","http://health.localhost:8080",8,null);
        final SqlServerAccessStore access=mock(SqlServerAccessStore.class);final SqlServerIdentityStore identity=mock(SqlServerIdentityStore.class);final SqlServerAccountLifecycleStore lifecycle=mock(SqlServerAccountLifecycleStore.class);final SqlServerSupportStore support=mock(SqlServerSupportStore.class);final SqlServerSecurityStore security=mock(SqlServerSecurityStore.class);final SqlServerTraceStore trace=mock(SqlServerTraceStore.class);
        final AnnotationConfigWebApplicationContext context=new AnnotationConfigWebApplicationContext();
        Harness(){this(null,true);}
        Harness(String missing,boolean securityConfig){context.setServletContext(servlet);context.addBeanFactoryPostProcessor(factory->{var beans=new LinkedHashMap<String,Object>();beans.put("mapper",mapper);beans.put("settings",settings);beans.put("sqlServerAccessStore",access);beans.put("sqlServerIdentityStore",identity);beans.put("sqlServerAccountLifecycleStore",lifecycle);beans.put("sqlServerSupportStore",support);beans.put("sqlServerSecurityStore",security);beans.put("sqlServerTraceStore",trace);if(!securityConfig)beans.put("passwords",new BCryptPasswordEncoder(12));beans.forEach((name,value)->{if(!name.equals(missing))factory.registerSingleton(name,value);});});context.register(SqlServerIdentityConfiguration.class);if(securityConfig)context.register(SqlServerSecurityConfiguration.class);}
        void refresh(){context.refresh();}
        @Override public void close(){context.close();}
    }
    @AfterEach void clean(){RequestContextHolder.resetRequestAttributes();TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
    @Test void exactSqlGraphReferencesAndNoLegacyOrDuplicateBeans()throws Exception{try(var h=new Harness()){h.refresh();var c=h.context;var access=c.getBean(Access.class);var identity=c.getBean(IdentityService.class);var lifecycle=c.getBean(AccountLifecycleService.class);var browser=c.getBean(BrowserSessionController.class);var support=c.getBean(SupportController.class);var errors=c.getBean(Errors.class);var passwords=c.getBean("passwords",PasswordEncoder.class);for(Class<?> type:List.of(Access.class,IdentityService.class,AccountLifecycleService.class,BrowserSessionController.class,SupportController.class,Errors.class,Errors.Advice.class,PasswordEncoder.class))assertEquals(1,c.getBeansOfType(type).size());assertSame(h.access,field(access,"accessStore"));assertSame(h.identity,field(identity,"identityStore"));assertSame(h.lifecycle,field(lifecycle,"sqlServer"));assertSame(h.identity,field(browser,"identityStore"));assertSame(h.support,field(support,"store"));assertSame(identity,field(browser,"service"));assertSame(identity,field(lifecycle,"identity"));assertSame(lifecycle,field(support,"lifecycle"));for(Object object:List.of(identity,browser,lifecycle))assertSame(h.settings,field(object,"settings"));for(Object object:List.of(identity,browser,support))assertSame(access,field(object,"access"));assertSame(passwords,field(identity,"passwords"));assertSame(passwords,field(lifecycle,"passwords"));assertSame(h.mapper,field(errors,"mapper"));assertSame(errors,field(c.getBean(Errors.Advice.class),"errors"));assertNull(field(identity,"attemptsRecorder"));for(Object object:List.of(access,identity,lifecycle,browser,support))assertNull(field(object,"sql"));assertTrue(passwords instanceof BCryptPasswordEncoder);assertEquals(12,field(passwords,"strength"));assertEquals(0,c.getBeansOfType(com.mavric.health.shared.Sql.class).size());assertEquals(0,c.getBeansOfType(AttemptRecorder.class).size());assertEquals(0,c.getBeansOfType(Bootstrap.class).size());verifyNoInteractions(h.access,h.identity,h.lifecycle,h.support,h.security,h.trace);}}
    @Test void singletonAccessUsesNativeProxyForTwoDifferentRequestsWithoutHeaderAuthority()throws Exception{try(var h=new Harness()){h.refresh();var access=h.context.getBean(Access.class);assertTrue(java.lang.reflect.Proxy.isProxyClass(field(access,"request").getClass()));for(String id:List.of(TENANT,OTHER)){var req=new MockHttpServletRequest(h.servlet);var tenant=new TenantRef(id,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("CORE"));req.setAttribute("health.tenant",tenant);req.addHeader("X-Tenant-Id",ID);RequestContextHolder.setRequestAttributes(new ServletRequestAttributes(req));assertSame(tenant,access.tenant());assertEquals(id,access.tenantId());assertSame(access,h.context.getBean(Access.class));}verifyNoInteractions(h.access);}}
    @Test void adviceIsExplicitAndUsesSharedMapperWithoutLeakingUnexpectedFailure(){try(var h=new Harness()){h.refresh();var req=new MockHttpServletRequest(h.servlet,"GET","/synthetic");var response=h.context.getBean(Errors.Advice.class).invalid(new IllegalArgumentException("private-canary"),req);assertEquals(400,response.getStatusCode().value());assertFalse(response.getBody().toString().contains("private-canary"));}}
    @Test void requiredExternalSuppliesNeverProduceLegacyFallback(){for(String missing:List.of("mapper","settings","passwords","sqlServerAccessStore","sqlServerIdentityStore","sqlServerAccountLifecycleStore","sqlServerSupportStore")){try(var h=new Harness(missing,false)){assertThrows(RuntimeException.class,h::refresh);verifyNoInteractions(h.access,h.identity,h.lifecycle,h.support);}}}
    @Test void configOutsideLegacyScanDoesNotAddRootSchedulingOrTransactionAop(){var scan=new ClassPathScanningCandidateComponentProvider(true);assertTrue(scan.findCandidateComponents("com.mavric.health").stream().noneMatch(bean->bean.getBeanClassName().startsWith("com.mavric.healthsqlserver.")));try(var h=new Harness(null,false)){h.refresh();assertEquals(1,SqlServerIdentityConfiguration.class.getDeclaredAnnotations().length);assertTrue(Arrays.stream(h.context.getBeanDefinitionNames()).noneMatch(name->name.toLowerCase(Locale.ROOT).contains("scheduled") || name.toLowerCase(Locale.ROOT).contains("flyway") || name.contains("transactionAdvisor")));assertTrue(h.context.getBeansOfType(javax.sql.DataSource.class).isEmpty());}}
    @Test void existingAfterCommitActorAndCookieHooksRetainCommitAndRollbackSemantics()throws Exception{try(var h=new Harness()){h.refresh();var actor=new Actor(ID,"Synthetic","synthetic@example.test",null,List.of("SAD"),"a".repeat(64));var publish=IdentityService.class.getDeclaredMethod("publishAfterCommit",HttpServletRequest.class,Actor.class);publish.setAccessible(true);var cookie=BrowserSessionController.class.getDeclaredMethod("cookieAfterCommit",jakarta.servlet.http.HttpServletResponse.class,String.class);cookie.setAccessible(true);var manager=new com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager();for(boolean rollback:List.of(false,true)){var req=new MockHttpServletRequest(h.servlet);var res=new MockHttpServletResponse();Runnable action=()->manager.outer(()->{try{publish.invoke(null,req,actor);cookie.invoke(null,res,"health_session=synthetic; HttpOnly");}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}assertNull(req.getAttribute("health.actor"));assertNull(res.getHeader("Set-Cookie"));if(rollback)throw new RuntimeException("synthetic cancel");return null;});if(rollback){assertThrows(RuntimeException.class,action::run);assertNull(req.getAttribute("health.actor"));assertNull(res.getHeader("Set-Cookie"));}else{action.run();assertSame(actor,req.getAttribute("health.actor"));assertNotNull(res.getHeader("Set-Cookie"));}}}}
}
